00189     public function __construct($args)
00190     {
00191         global $bearsamppWinbinder;
00192 
00193         // Initialize dialog (child class can load data, etc.)
00194         if (!$this->initializeDialog($args)) {
00195             return;
00196         }
00197 
00198         $bearsamppWinbinder->reset();
00199         $this->wbWindow = $bearsamppWinbinder->createAppWindow(
00200             $this->getWindowTitle(),
00201             490,
00202             200,
00203             WBC_NOTIFY,
00204             WBC_KEYDOWN | WBC_KEYUP
00205         );
00206 
00207         // Create form fields (implemented by child class)
00208         $this->createFormFields($bearsamppWinbinder);
00209 
00210         // Create progress bar and buttons
00211         $this->createButtons($bearsamppWinbinder);
00212 
00213         // Set up event handler
00214         $bearsamppWinbinder->setHandler($this->wbWindow, $this, 'processWindow');
00215         $bearsamppWinbinder->mainLoop();
00216         $bearsamppWinbinder->reset();
00217     }
