00284     public function processWindow($window, $id, $ctrl, $param1, $param2)
00285     {
00286         global $bearsamppWinbinder;
00287 
00288         // Handle save button
00289         if ($id == $this->wbBtnSave[WinBinder::CTRL_ID]) {
00290             $this->handleSave($window);
00291             return;
00292         }
00293 
00294         // Handle delete button (if in edit mode)
00295         if ($this->isEditMode() && $id == $this->wbBtnDelete[WinBinder::CTRL_ID]) {
00296             $this->handleDelete($window);
00297             return;
00298         }
00299 
00300         // Handle cancel button or window close
00301         if ($id == IDCLOSE || $id == $this->wbBtnCancel[WinBinder::CTRL_ID]) {
00302             $bearsamppWinbinder->destroyWindow($window);
00303             return;
00304         }
00305 
00306         // Handle custom events (implemented by child class)
00307         $this->handleCustomEvent($window, $id, $ctrl, $param1, $param2);
00308     }
00309 
00320     protected function handleCustomEvent($window, $id, $ctrl, $param1, $param2)
00321     {
00322         // Default: do nothing
00323         // Child classes can override to handle specific events
00324     }
00325 
00332     protected function handleSave($window)
00333     {
00334         global $bearsamppWinbinder;
00335 
00336         $bearsamppWinbinder->setProgressBarMax($this->wbProgressBar, $this->getGaugeSave() + 1);
00337         $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00338 
00339         // Get form values
00340         $values = $this->getFormValues($bearsamppWinbinder);
00341 
00342         // Validate input
00343         $validation = $this->validateInput($values);
00344         if (!$validation['valid']) {
00345             $bearsamppWinbinder->messageBoxError(
00346                 $validation['error'],
00347                 $this->getDialogTitle()
00348             );
00349             $bearsamppWinbinder->resetProgressBar($this->wbProgressBar);
00350             return;
00351         }
00352 
00353         // Check if item already exists (for add or rename operations)
00354         if ($this->itemExists($values)) {
00355             $bearsamppWinbinder->resetProgressBar($this->wbProgressBar);
00356             return;
00357         }
00358 
00359         // Save the item
00360         if ($this->saveItem($values)) {
00361             $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00362 
00363             // Restart service
00364             $this->restartService();
00365             $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00366 
00367             // Show success message
00368             $bearsamppWinbinder->messageBoxInfo(
00369                 $this->getSaveSuccessMessage($values),
00370                 $this->getDialogTitle()
00371             );
00372             $bearsamppWinbinder->destroyWindow($window);
00373         } else {
00374             $bearsamppWinbinder->messageBoxError(
00375                 $this->getSaveErrorMessage(),
00376                 $this->getDialogTitle()
00377             );
00378             $bearsamppWinbinder->resetProgressBar($this->wbProgressBar);
00379         }
00380     }
00381 
00388     protected function handleDelete($window)
00389     {
00390         global $bearsamppWinbinder;
00391 
00392         $bearsamppWinbinder->setProgressBarMax($this->wbProgressBar, $this->getGaugeDelete() + 1);
00393 
00394         // Confirm deletion
00395         $confirm = $bearsamppWinbinder->messageBoxYesNo(
00396             $this->getDeleteConfirmMessage(),
00397             $this->getDeleteDialogTitle()
00398         );
00399 
00400         $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00401 
00402         if ($confirm) {
00403             if ($this->deleteItem()) {
00404                 $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00405 
00406                 // Restart service
00407                 $this->restartService();
00408                 $bearsamppWinbinder->incrProgressBar($this->wbProgressBar);
00409 
00410                 // Show success message
00411                 $bearsamppWinbinder->messageBoxInfo(
00412                     $this->getDeleteSuccessMessage(),
00413                     $this->getDeleteDialogTitle()
00414                 );
00415                 $bearsamppWinbinder->destroyWindow($window);
00416             } else {
00417                 $bearsamppWinbinder->messageBoxError(
00418                     $this->getDeleteErrorMessage(),
00419                     $this->getDeleteDialogTitle()
00420                 );
00421                 $bearsamppWinbinder->resetProgressBar($this->wbProgressBar);
00422             }
00423         } else {
00424             $bearsamppWinbinder->resetProgressBar($this->wbProgressBar);
00425         }
00426     }
